package com.sajuppugi.gift.api; import com.sajuppugi.common.api.*; import com.sajuppugi.common.idempotency.IdempotencyKey; import com.sajuppugi.gift.application.DirectGiftFulfillmentService; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @ConditionalOnProperty(name="app.gift.purchases-enabled",havingValue="true") @RequestMapping("/api/v1/direct-payment-batches") public class DirectGiftFulfillmentController {private final DirectGiftFulfillmentService service; public DirectGiftFulfillmentController(DirectGiftFulfillmentService s){service=s;} @PostMapping("/{batchId}/gift-fulfillment") public ApiResponse<List<DirectGiftFulfillmentService.Link>> fulfill(Authentication a,@PathVariable UUID batchId){try{return ApiResponse.of(service.fulfill(UUID.fromString(a.getName()),batchId));}catch(IllegalArgumentException e){throw new ApiException(ErrorCode.AUTHENTICATION_REQUIRED);}} @PostMapping("/recipients/{recipientId}/link-reissue") public ApiResponse<DirectGiftFulfillmentService.Link> reissue(Authentication a,@PathVariable UUID recipientId,@RequestHeader("Idempotency-Key") String key){try{return ApiResponse.of(service.reissue(UUID.fromString(a.getName()),recipientId,new IdempotencyKey(key)));}catch(IllegalArgumentException e){throw new ApiException(ErrorCode.AUTHENTICATION_REQUIRED);}}}
